import React from 'react';
import ReactDOM from 'react-dom';
import {
  Breadcrumb,
  BreadcrumbItem,
  OverflowMenu,
  OverflowMenuItem,
} from 'carbon-components-react';

// Simulate the createComponentToggle HOC by wrapping OverflowMenu
// and giving it a different displayName (e.g. 'ComponentToggle')
const WrappedOverflowMenu = (props) => <OverflowMenu {...props} />;
WrappedOverflowMenu.displayName = 'ComponentToggle';

function App() {
  return (
    // constrain width to force the overflow menu to appear
    <div style={{ width: '240px', border: '1px solid #ddd', padding: '1rem' }}>
      <Breadcrumb aria-label="Breadcrumb with overflow"> 
        <BreadcrumbItem href="#">Home</BreadcrumbItem>
        <BreadcrumbItem href="#">Section</BreadcrumbItem>
        <BreadcrumbItem>
          {/* WrappedOverflowMenu does NOT match the displayName check in BreadcrumbItem */}
          <WrappedOverflowMenu>
            <OverflowMenuItem itemText="Option A" />
            <OverflowMenuItem itemText="Option B" />
            <OverflowMenuItem itemText="Option C" />
          </WrappedOverflowMenu>
        </BreadcrumbItem>
        <BreadcrumbItem href="#">Subsection</BreadcrumbItem>
        <BreadcrumbItem href="#" isCurrentPage>
          Current Page
        </BreadcrumbItem>
      </Breadcrumb>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
